const FIRESTORE_WRITE_EVENT = 'hd-manager:firestore-write';
const ACTIVITY_LOG_COLLECTION_NAME = 'activityLogs';
const ACTIVITY_LOG_IGNORED_COLLECTIONS = new Set([ACTIVITY_LOG_COLLECTION_NAME]);
const resolveFirebaseWriterDomain = (operation = '', collectionName = '') => {
  const value = `${operation} ${collectionName}`.toLowerCase();
  if (/(order|payment|payos|sepay|bank|debt)/.test(value)) return 'ORDER_PAYMENT_DEBT';
  if (/(warehouse|inventory|stock|dispatch|delivery)/.test(value)) return 'WAREHOUSE_INVENTORY';
  if (/(employee|attendance|payroll|salary|leave|asset)/.test(value)) return 'EMPLOYEE_HR';
  if (/(product|price|unit)/.test(value)) return 'PRODUCT';
  if (/(customer|company|branch)/.test(value)) return 'CUSTOMER';
  if (/(identity|auth|session|device)/.test(value)) return 'AUTH_IDENTITY';
  return 'PLATFORM_OTHER';
};

const buildFirebaseWriterContext = (operation, context = {}) => ({
  file: context.file || 'src/App.jsx',
  functionName: context.functionName || operation,
  domain: context.domain || resolveFirebaseWriterDomain(operation, context.collection),
  operation,
  collection: context.collection || '',
  mode: isVpsMode ? vpsDataMode : 'legacy',
});

const createVpsStagingFirebaseWriteError = (operation, context = {}) => {
  const writerContext = buildFirebaseWriterContext(operation, context);
  const error = new Error(
    writerContext.domain === 'WAREHOUSE_INVENTORY' && !inventoryVpsEnabled
      ? 'Inventory VPS API is disabled until the Warehouse/StockLedger contract is approved.'
      : `Firebase write (${operation}) is disabled in VPS mode for ${writerContext.domain}. `
        + `Use the approved VPS API contract instead.`,
  );
  error.code = 'firebase-writer-disabled-in-vps-staging';
  error.writerContext = writerContext;
  recordStartupEvent('firebase.writer.blocked', writerContext, 'error');
  if (typeof console !== 'undefined' && typeof console.error === 'function') {
    console.error('[firebase-writer-blocked]', writerContext);
  }
  return error;
};

const assertFirebaseWriteAllowed = (operation, context = {}) => {
  if (isVpsMode) throw createVpsStagingFirebaseWriteError(operation, context);
};

const runNonBlockingStateUpdate = (callback) => {
  if (typeof startTransition === 'function') {
    startTransition(callback);
    return;
  }
  callback();
};
let activityAuditContext = {};
let activityAuditSuppressionDepth = 0;

const setActivityAuditContext = (context = {}) => {
  activityAuditContext = context && typeof context === 'object' ? context : {};
};

const getCollectionNameFromDocRef = (documentRef) => {
  const rawPath = documentRef?.path
    || (Array.isArray(documentRef?._key?.path?.segments) ? documentRef._key.path.segments.join('/') : '');
  const parts = `${rawPath || ''}`.split('/').filter(Boolean);
  const dataIndex = parts.lastIndexOf('data');
  if (dataIndex >= 0 && parts[dataIndex + 1]) return parts[dataIndex + 1];
  return parts.length >= 2 ? parts[parts.length - 2] : '';
};

const getDocumentPathFromDocRef = (documentRef) => (
  documentRef?.path
  || (Array.isArray(documentRef?._key?.path?.segments) ? documentRef._key.path.segments.join('/') : '')
  || ''
);

const getAuditActionForWrite = (payload = {}, options = {}) => {
  if (payload?.isArchived === true || payload?.deletedAt) return 'archive';
  if (payload?.restoredAt) return 'restore';
  if (options?.merge) return 'update';
  return 'upsert';
};

const getAuditRecordLabel = (collectionName = '', payload = {}, documentRef = {}) => {
  const candidates = [
    payload?.orderCode,
    payload?.code,
    payload?.invoiceCode,
    payload?.customerName,
    payload?.name,
    payload?.title,
    payload?.phone,
    payload?.productName,
    payload?.groupName,
    payload?.messageText,
    documentRef?.id
  ];
  const label = candidates.find(value => `${value || ''}`.trim());
  return `${label || collectionName || documentRef?.id || 'document'}`.slice(0, 160);
};

const getAuditCompanyId = (collectionName = '', payload = {}, documentRef = {}) => {
  if (collectionName === 'companies') return documentRef?.id || payload?.id || activityAuditContext.companyId || '';
  return payload?.companyId
    || payload?.sourceCompanyId
    || payload?.company?.id
    || activityAuditContext.companyId
    || '';
};

const buildActivityAuditLogPayload = ({ documentRef, action, payload = {}, options = {} }) => {
  const collectionName = getCollectionNameFromDocRef(documentRef);
  const companyId = getAuditCompanyId(collectionName, payload, documentRef);
  if (!db || !collectionName || ACTIVITY_LOG_IGNORED_COLLECTIONS.has(collectionName) || !companyId) return null;

  const fieldNames = payload && typeof payload === 'object' && !Array.isArray(payload)
    ? Object.keys(payload).filter(key => key !== 'updatedAt' && key !== 'createdAt').slice(0, 80)
    : [];
  const actor = activityAuditContext || {};
  const resolvedAction = action === 'delete' ? 'delete' : getAuditActionForWrite(payload, options);
  return {
    id: `act_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`,
    companyId,
    action: resolvedAction,
    collectionName,
    documentId: documentRef?.id || '',
    documentPath: getDocumentPathFromDocRef(documentRef),
    recordLabel: getAuditRecordLabel(collectionName, payload, documentRef),
    fieldNames,
    fieldCount: fieldNames.length,
    actorId: actor.userId || actor.actorId || '',
    actorName: actor.userName || actor.actorName || '',
    actorPhone: actor.userPhone || '',
    actorRole: actor.userRole || actor.role || '',
    actorType: actor.userType || actor.type || '',
    platform: typeof Capacitor !== 'undefined' ? Capacitor.getPlatform() : 'web',
    createdAt: new Date().toISOString()
  };
};

const writeActivityAuditLog = async (logPayload) => {
  if (isVpsMode) return;
  if (!db || !logPayload || activityAuditSuppressionDepth > 0) return;
  try {
    await firebaseSetDoc(
      doc(db, 'artifacts', appId, 'public', 'data', ACTIVITY_LOG_COLLECTION_NAME, logPayload.id),
      sanitizeFirestoreWritePayload(logPayload),
      { merge: true }
    );
  } catch (error) {
    console.warn('Không thể ghi nhật ký hoạt động:', error);
  }
};

const queueActivityAuditLog = (args) => {
  if (activityAuditSuppressionDepth > 0) return;
  const logPayload = buildActivityAuditLogPayload(args);
  if (!logPayload) return;
  setTimeout(() => {
    writeActivityAuditLog(logPayload);
  }, 0);
};

const withActivityAuditSuppressed = async (task) => {
  activityAuditSuppressionDepth += 1;
  try {
    return await task();
  } finally {
    activityAuditSuppressionDepth = Math.max(0, activityAuditSuppressionDepth - 1);
  }
};

const notifyFirestoreDocumentChanged = (documentRef, action = 'set', payload = null, options = {}) => {
  if (typeof window === 'undefined') return;
  const collectionName = getCollectionNameFromDocRef(documentRef);
  if (!collectionName) return;
  window.dispatchEvent(new CustomEvent(FIRESTORE_WRITE_EVENT, {
    detail: {
      action,
      collectionName,
      documentPath: documentRef?.path || '',
      documentId: documentRef?.id || '',
      payload,
      options,
      at: new Date().toISOString()
    }
  }));
};

const isPlainSerializableObject = (value) => {
  if (!value || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
};

const sanitizeFirestoreWriteValue = (value, { inArray = false } = {}) => {
  if (value === undefined) return inArray ? null : undefined;
  if (value === null) return null;
  if (value instanceof Date) return value;
  if (Array.isArray(value)) {
    return value.map(item => sanitizeFirestoreWriteValue(item, { inArray: true }));
  }
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value !== 'object') return value;

  // Preserve Firebase sentinel values such as increment(1), plus any non-plain SDK objects.
  if (!isPlainSerializableObject(value)) return value;

  return Object.entries(value).reduce((acc, [key, nestedValue]) => {
    const sanitizedValue = sanitizeFirestoreWriteValue(nestedValue);
    if (sanitizedValue !== undefined) acc[key] = sanitizedValue;
    return acc;
  }, {});
};

const sanitizeFirestoreWritePayload = (payload) => {
  const sanitizedPayload = sanitizeFirestoreWriteValue(payload);
  return sanitizedPayload && typeof sanitizedPayload === 'object' ? sanitizedPayload : {};
};

const setDoc = async (documentRef, payload, options) => {
  const collectionName = getCollectionNameFromDocRef(documentRef);
  assertFirebaseWriteAllowed('setDoc', {
    functionName: 'setDoc',
    collection: collectionName,
  });
  const sanitizedPayload = sanitizeFirestoreWritePayload(payload);
  const result = await recordFirestoreOperation('setDoc', {
    path: getDocumentPathFromDocRef(documentRef),
    id: documentRef?.id || '',
    merge: Boolean(options?.merge),
  }, () => firebaseSetDoc(documentRef, sanitizedPayload, options));
  notifyFirestoreDocumentChanged(documentRef, 'set', sanitizedPayload, options || {});
  queueActivityAuditLog({ documentRef, action: 'set', payload: sanitizedPayload, options });
  return result;
};

const deleteDoc = async (documentRef) => {
  const collectionName = getCollectionNameFromDocRef(documentRef);
  assertFirebaseWriteAllowed('deleteDoc', {
    functionName: 'deleteDoc',
    collection: collectionName,
  });
  const result = await recordFirestoreOperation('deleteDoc', {
    path: getDocumentPathFromDocRef(documentRef),
    id: documentRef?.id || '',
  }, () => firebaseDeleteDoc(documentRef));
  notifyFirestoreDocumentChanged(documentRef, 'delete');
  queueActivityAuditLog({ documentRef, action: 'delete', payload: {}, options: {} });
  return result;
};

const getFirestoreTargetPath = (targetRef) => {
  if (!targetRef) return '';
  if (targetRef.path) return targetRef.path;
  try {
    return targetRef?._query?.path?.canonicalString?.() || '';
  } catch {
    return '';
  }
};

const getDocs = async (queryRef) => recordFirestoreOperation('getDocs', {
  path: getFirestoreTargetPath(queryRef),
}, () => firebaseGetDocs(queryRef));

const getDoc = async (documentRef) => recordFirestoreOperation('getDoc', {
  path: getDocumentPathFromDocRef(documentRef),
  id: documentRef?.id || '',
}, () => firebaseGetDoc(documentRef));

const runTransaction = async (database, updateFunction, options) => {
  assertFirebaseWriteAllowed('runTransaction', {
    functionName: 'runTransaction',
  });
  return recordFirestoreOperation('runTransaction', {
    appName: database?.app?.name || '',
  }, () => firebaseRunTransaction(database, updateFunction, options));
};

const onSnapshot = (targetRef, ...snapshotArgs) => {
  const path = getFirestoreTargetPath(targetRef);
  const subscribeSpan = createPerformanceSpan('realtime.subscribe', {
    provider: 'firestore',
    path,
  });
  const wrappedArgs = [...snapshotArgs];
  const nextIndex = typeof wrappedArgs[0] === 'function' ? 0 : 1;
  const nextHandler = wrappedArgs[nextIndex];
  const errorHandler = wrappedArgs[nextIndex + 1];

  if (typeof nextHandler === 'function') {
    wrappedArgs[nextIndex] = (snapshot) => {
      if (isPerformanceMonitorEnabled()) {
        recordPerformanceEvent('realtime.snapshot', {
          provider: 'firestore',
          path,
          docs: typeof snapshot?.size === 'number' ? snapshot.size : undefined,
          changes: getRealtimeDataChangeCount(snapshot) ?? undefined,
          fromCache: snapshot?.metadata?.fromCache,
          hasPendingWrites: snapshot?.metadata?.hasPendingWrites,
        });
      }
      return nextHandler(snapshot);
    };
  }

  if (typeof errorHandler === 'function') {
    wrappedArgs[nextIndex + 1] = (error) => {
      recordPerformanceEvent('realtime.error', {
        provider: 'firestore',
        path,
        error: {
          name: error?.name,
          message: error?.message,
          code: error?.code,
        },
      }, 'error');
      return errorHandler(error);
    };
  }

  try {
    const unsubscribe = firebaseOnSnapshot(targetRef, ...wrappedArgs);
    const closeSubscription = trackRealtimeSubscription({ provider: 'firestore', path });
    subscribeSpan.end({ status: 'subscribed' });
    return () => {
      recordPerformanceEvent('realtime.unsubscribe', { provider: 'firestore', path });
      closeSubscription();
      unsubscribe();
    };
  } catch (error) {
    subscribeSpan.fail(error);
    throw error;
  }
};
