const DEPARTMENT_ACCOUNT_OPTIONS = ['Kế toán & nhân sự', 'Tài xế', 'Sản xuất', 'Kinh doanh', SALES_COLLABORATOR_POSITION, WAREHOUSE_EXPORT_POSITION];
const ORDER_REQUEST_QUANTITY_UNIT_OPTIONS = PRODUCT_PRICING_UNIT_OPTIONS;

const getEmployeePositionLabel = (position = '') => normalizeEmployeePosition(position) || 'Nhân sự';



const isAccountingPosition = (position = '') => ['Chủ doanh nghiệp', 'Kế toán & nhân sự'].includes(normalizeEmployeePosition(position));
const usesCompanyHomeDashboard = (employee, currentUser) => currentUser?.role === 'super_admin'
  || employee?.role === 'super_admin' || isOwnerAccountUser(employee,currentUser) || isAccountingPosition(employee?.position || '');
const isSalesCollaboratorPosition = (position = '') => normalizeEmployeePosition(position) === SALES_COLLABORATOR_POSITION;

const isDriverPosition = (position = '') => normalizeEmployeePosition(position) === 'Tài xế';


const getPrimaryDeliveryAssignmentId = (source = {}) => getDeliveryAssignmentIds(source)[0] || '';
const isWarehouseScalePosition = (position = '') => normalizeEmployeePosition(position) === WAREHOUSE_EXPORT_POSITION;






const isEmployeeSalesCollaboratorPosition = (employee = {}) => employeeHasPosition(employee, isSalesCollaboratorPosition);
const isEmployeeDriverPosition = (employee = {}) => employeeHasPosition(employee, isDriverPosition);

const isEmployeeWarehouseScalePosition = (employee = {}) => employeeHasPosition(employee, isWarehouseScalePosition);
const getEmployeePositionSummary = (employee = {}) => getEmployeePositionValues(employee).join(' + ') || getEmployeePositionLabel(employee?.position);

const getSalesLeaderCommissionPercent = (employee = {}) => {
  const parsed = parseFloat(employee?.salesLeaderCommissionPercent ?? employee?.leaderCommissionPercent ?? employee?.managerCommissionPercent ?? 0);
  return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
};

