const installFirestoreInternalErrorGuard = () => {
  if (typeof window === 'undefined' || window.__HD_FIRESTORE_INTERNAL_ERROR_GUARD__) return;
  window.__HD_FIRESTORE_INTERNAL_ERROR_GUARD__ = true;
  const notifyRecovery = () => {
    window.dispatchEvent(new CustomEvent('hd-manager:firestore-internal-error', {
      detail: { at: new Date().toISOString() }
    }));
  };
  window.addEventListener('error', (event) => {
    if (!isFirestoreInternalAssertionError(event?.error || event?.message)) return;
    event.preventDefault?.();
    event.stopImmediatePropagation?.();
    notifyRecovery();
  }, true);
  window.addEventListener('unhandledrejection', (event) => {
    if (!isFirestoreInternalAssertionError(event?.reason)) return;
    event.preventDefault?.();
    event.stopImmediatePropagation?.();
    notifyRecovery();
  }, true);
};

installFirestoreInternalErrorGuard();

const toFirestoreRestValue = (value) => {
  if (value === undefined) return null;
  if (value === null) return { nullValue: null };
  if (value instanceof Date) return { timestampValue: value.toISOString() };
  if (Array.isArray(value)) {
    return { arrayValue: { values: value.map(toFirestoreRestValue).filter(Boolean) } };
  }
  if (typeof value === 'boolean') return { booleanValue: value };
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return { nullValue: null };
    return Number.isInteger(value) ? { integerValue: String(value) } : { doubleValue: value };
  }
  if (typeof value === 'object') {
    const fields = Object.entries(value).reduce((acc, [key, nestedValue]) => {
      const converted = toFirestoreRestValue(nestedValue);
      if (converted) acc[key] = converted;
      return acc;
    }, {});
    return { mapValue: { fields } };
  }
  return { stringValue: `${value}` };
};

const toFirestoreRestFields = (data = {}) => Object.entries(data).reduce((acc, [key, value]) => {
  const converted = toFirestoreRestValue(value);
  if (converted) acc[key] = converted;
  return acc;
}, {});

const fromFirestoreRestValue = (value = {}) => {
  if (Object.prototype.hasOwnProperty.call(value, 'nullValue')) return null;
  if (Object.prototype.hasOwnProperty.call(value, 'booleanValue')) return Boolean(value.booleanValue);
  if (Object.prototype.hasOwnProperty.call(value, 'integerValue')) return Number(value.integerValue);
  if (Object.prototype.hasOwnProperty.call(value, 'doubleValue')) return Number(value.doubleValue);
  if (Object.prototype.hasOwnProperty.call(value, 'timestampValue')) return value.timestampValue;
  if (Object.prototype.hasOwnProperty.call(value, 'stringValue')) return value.stringValue;
  if (Object.prototype.hasOwnProperty.call(value, 'bytesValue')) return value.bytesValue;
  if (Object.prototype.hasOwnProperty.call(value, 'referenceValue')) return value.referenceValue;
  if (value.geoPointValue) return { ...value.geoPointValue };
  if (value.arrayValue) return (value.arrayValue.values || []).map(fromFirestoreRestValue);
  if (value.mapValue) return fromFirestoreRestFields(value.mapValue.fields || {});
  return null;
};

const fromFirestoreRestFields = (fields = {}) => Object.entries(fields || {}).reduce((acc, [key, value]) => {
  acc[key] = fromFirestoreRestValue(value);
  return acc;
}, {});

const buildFirestoreRestDocumentUrl = (collectionName, documentId, { merge = false, fieldPaths = [] } = {}) => {
  if (isVpsMode) return '';
  const projectId = activeFirebaseConfig?.projectId || '';
  return buildFirebaseRestDocumentUrl(projectId, appId, collectionName, documentId, { merge, fieldPaths });
};

const saveBlobFile = async (filename, blob) => {
  if (!blob) return { status: 'unsupported', path: filename };

  if (Capacitor.getPlatform() !== 'web') {
    try {
      const path = `HDManager/${filename}`;
      const base64Data = await blobToBase64(blob);
      await Filesystem.writeFile({
        path,
        data: base64Data,
        directory: Directory.Documents,
        recursive: true
      });
      const fileUri = await Filesystem.getUri({
        path,
        directory: Directory.Documents
      });
      return { status: 'saved', path, uri: fileUri?.uri || '' };
    } catch (error) {
      return { status: 'unsupported', path: filename, error };
    }
  }

  if (typeof window === 'undefined' || typeof document === 'undefined') return { status: 'unsupported', path: filename };
  const objectUrl = window.URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = objectUrl;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  // Keep the object URL alive long enough for browsers to finish a download,
  // especially when several share images fall back to downloads together.
  window.setTimeout(() => window.URL.revokeObjectURL(objectUrl), 2000);
  return { status: 'downloaded', path: filename };
};

const shareBlobFile = async ({
  filename,
  blob,
  title = '',
  text = '',
  dialogTitle = '',
  fallbackToDownload = true,
  preparedNativeFile = null
}) => {
  if (!blob) return { status: 'unsupported', path: filename };

  if (Capacitor.getPlatform() !== 'web') {
    try {
      let nativeFile = preparedNativeFile?.uri ? preparedNativeFile : null;

      for (let attempt = 0; attempt < 2; attempt += 1) {
        try {
          if (!nativeFile || attempt > 0) {
            nativeFile = await writeBlobToShareCache(filename, blob);
          }
          const { path, uri } = nativeFile || {};
          const capability = await CapacitorShare.canShare().catch(() => ({ value: false }));
          if (capability?.value && uri) {
            await CapacitorShare.share({
              title,
              text,
              dialogTitle: dialogTitle || title,
              files: [uri]
            });
            return { status: 'shared', path, uri };
          }
          if (!fallbackToDownload) return { status: 'unsupported', path, uri };
          return saveBlobFile(filename, blob);
        } catch (error) {
          if (isShareCancelled(error)) {
            return { status: 'cancelled' };
          }
          if (nativeFile === preparedNativeFile && attempt === 0) {
            recordPerformanceEvent('share_invoice.native_file_rebuilt', { filename }, 'warn');
            nativeFile = null;
            continue;
          }
          throw error;
        }
      }
    } catch (error) {
      if (isShareCancelled(error)) {
        return { status: 'cancelled' };
      }
      if (!fallbackToDownload) return { status: 'unsupported', path: filename, error };
      const saved = await saveBlobFile(filename, blob);
      return { ...saved, shareError: error };
    }
  }

  try {
    if (typeof navigator !== 'undefined' && typeof navigator.share === 'function') {
      const file = new File([blob], filename, { type: blob.type || 'application/octet-stream' });
      if (!navigator.canShare || navigator.canShare({ files: [file] })) {
        try {
          await navigator.share({ title, text, files: [file] });
        } catch (error) {
          if (isShareCancelled(error)) {
            return { status: 'cancelled' };
          }
          await navigator.share({ title, files: [file] });
        }
        return { status: 'shared', path: filename };
      }
    }
  } catch (error) {
    if (isShareCancelled(error)) {
      return { status: 'cancelled' };
    }
  }

  if (!fallbackToDownload) return { status: 'unsupported', path: filename };
  return saveBlobFile(filename, blob);
};



