const requestOrderRequestDraftFromGeminiTranscript = async (transcript, context = {}) => {
  if (!GEMINI_PROXY_ENABLED) {
    throw new Error('Chưa cấu hình Gemini API key cho nhập giọng nói.');
  }

  const prompt = buildOrderRequestBatchVoicePrompt(context);

  let response;
  try {
    response = await requestGeminiGenerateContent({
      contents: [{
        role: 'user',
        parts: [
          { text: prompt },
          { text: `Câu nói cần xử lý: ${transcript}` }
        ]
      }],
      generationConfig: {
        responseMimeType: 'application/json'
      }
    });
  } catch (error) {
    throw new Error('Không kết nối được tới Gemini để đọc giọng nói. Bạn hãy kiểm tra mạng rồi thử lại.');
  }

  const data = await response.json().catch(() => null);
  if (!response.ok) {
    const apiMessage = data?.error?.message || '';
    if (/quota|rate|busy|overloaded/i.test(apiMessage)) {
      throw new Error('Gemini đang bận hoặc tạm vượt giới hạn. Bạn hãy thử lại sau ít phút.');
    }
    throw new Error(apiMessage || 'AI chưa đọc được câu nói này. Bạn hãy đọc chậm và rõ hơn.');
  }

  const rawText = (data?.candidates?.[0]?.content?.parts || [])
    .map((part) => part?.text || '')
    .join('')
    .trim();
  const parsed = extractJsonPayload(rawText);

  if (!parsed || typeof parsed !== 'object') {
    throw new Error('AI chưa tạo ra dữ liệu hợp lệ từ câu nói này.');
  }

  return parsed;
};

