      if (!rowDate || rowDate < startDate || rowDate > endDate) return total;
      return {
        revenue: total.revenue + (Number(row.revenue) || 0),
        expense: total.expense + (Number(row.expense) || 0),
        profit: total.profit + (Number(row.profit) || 0)
      };
