function DebtManagementViewLegacy({ isAccounting, isDriver, employee, customers, orders, payments, employees, onAddPayment }) {
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [newPayment, setNewPayment] = useState({ amount: '', note: '', date: getTodayString() });

  const totalCompanyDebt = customers.reduce((sum, cus) => sum + getCustomerDebt(cus, orders, payments), 0);

  const handlePaymentSubmit = (e) => {
    e.preventDefault();
    if (!selectedCustomer) return;
    onAddPayment({ customerId: selectedCustomer.id, amount: parseInt(parseInputCurrency(newPayment.amount)) || 0, note: newPayment.note || (isDriver ? 'Tài xế thu tiền mặt' : 'Thu nợ'), date: newPayment.date });
    setShowPaymentModal(false); setNewPayment({ amount: '', note: '', date: getTodayString() });
  };

  if (selectedCustomer) {
    const currentDebt = getCustomerDebt(selectedCustomer, orders, payments);
    return (
      <div className="space-y-4 animate-in fade-in pb-16">
        <button onClick={() => setSelectedCustomer(null)} className="text-gray-500 flex items-center text-sm font-semibold mb-2"><ChevronLeft size={18} className="mr-1" /> Trở về danh sách</button>
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-50">
          <h2 className="font-bold text-xl text-gray-800 mb-4">{selectedCustomer.name}</h2>
          <div className="bg-red-50 border border-red-100 rounded-xl p-4 flex justify-between items-center mb-6">
            <span className="text-red-800 font-medium">Khách Đang Nợ:</span>
            <span className="text-2xl font-black text-red-600">{formatCurrency(currentDebt)} đ</span>
          </div>
          
          <button onClick={() => setShowPaymentModal(true)} className="w-full py-4 rounded-xl font-bold text-white shadow-lg flex justify-center items-center gap-2 bg-blue-600 hover:bg-blue-700">
            {isDriver ? <Banknote size={20}/> : <Wallet size={20}/>} {isDriver ? 'Báo Tài Xế Đã Thu Tiền' : 'Lập Phiếu Thu Nợ'}
          </button>
        </div>

        {showPaymentModal && (
          <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl p-5 w-full max-w-sm animate-in zoom-in-95">
              <h3 className="font-bold text-lg mb-4">{isDriver ? 'Báo Thu Tiền' : 'Ghi nhận Thanh toán'}</h3>
              <form onSubmit={handlePaymentSubmit} className="space-y-3">
                <input required type="tel" value={formatInputCurrency(newPayment.amount)} onChange={e=>setNewPayment({...newPayment, amount: parseInputCurrency(e.target.value)})} className="w-full border p-3 rounded-xl text-lg font-bold text-emerald-600 outline-none" placeholder="Số tiền (VNĐ)" />
                <input type="text" value={newPayment.note} onChange={e=>setNewPayment({...newPayment, note: capitalizeFirst(e.target.value)})} className="w-full border p-3 rounded-xl text-sm outline-none" placeholder="Ghi chú (không bắt buộc)" />
                <div className="flex gap-2 mt-4">
                  <button type="button" onClick={() => setShowPaymentModal(false)} className="flex-1 bg-gray-100 py-3 rounded-xl text-gray-700 font-bold">Hủy</button>
                  <button type="submit" className="flex-1 bg-emerald-500 text-white py-3 rounded-xl font-bold">Xác nhận thu</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-4 animate-in fade-in pb-16">
      {isAccounting && (
        <div className="bg-gradient-to-r from-red-500 to-orange-500 p-5 rounded-2xl shadow-md text-white mb-6">
          <p className="text-red-100 text-xs font-bold uppercase tracking-wider mb-1">Tổng Công Nợ Thị Trường</p>
          <h3 className="text-3xl font-black">{formatCurrency(totalCompanyDebt)} đ</h3>
        </div>
      )}
      
      <div className="bg-white px-3 py-2 rounded-lg border border-gray-100 shadow-sm flex items-center gap-2 mb-4">
        <Search size={18} className="text-gray-400" />
        <input data-hd-search-input="true" type="text" placeholder="Tìm kiếm khách nợ..." className="flex-1 text-sm outline-none" />
      </div>

      <div className="space-y-3">
        {customers.map(cus => {
          const debt = getCustomerDebt(cus, orders, payments);
          if (debt <= 0) return null; 
          return (
            <div key={cus.id} onClick={() => setSelectedCustomer(cus)} className="bg-white p-4 rounded-xl shadow-sm border border-gray-50 flex justify-between items-center cursor-pointer hover:bg-gray-50 transition">
              <div>
                <h3 className="font-bold text-gray-800 text-sm">{cus.name}</h3>
                <span className="text-[10px] text-gray-500 flex items-center mt-1"><MapPin size={10} className="mr-1"/> {cus.address}</span>
              </div>
              <div className="text-right">
                <span className="block font-bold text-red-500">{formatCurrency(debt)} đ</span>
                <span className="text-[10px] text-gray-400">Cần thu</span>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  );
}

const EMPTY_DEBT_SEARCH_STORE=Object.freeze({subscribe:()=>()=>{},getSnapshot:()=>''});
function DebtManagementView({ searchStore = null, isAccounting, isDriver, employee, customers, orders, payments, expenses = [], onAddRepayment, canRecordRepayment = false, warehouseImports = [], employees, onAddPayment, onDeletePayment, canViewAllDebt = false, canViewAssignedDebt = false, canRecordPayment = false, canEditDebt = false, canDeleteDebt = false, focusCustomerId = '', onFocusCustomerHandled, searchKeyword: externalSearchKeyword, setSearchKeyword: setExternalSearchKeyword, showSearchBox: externalShowSearchBox, setShowSearchBox: setExternalShowSearchBox, showFilterPanel: externalShowFilterPanel, setShowFilterPanel: setExternalShowFilterPanel }) {
  const [selectedCustomerId, setSelectedCustomerId] = useState(null);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [isSavingDebtPayment, setIsSavingDebtPayment] = useState(false);
  const [debtPaymentStatus, setDebtPaymentStatus] = useState('');
  const debtPaymentSubmitRef = useRef(false);
  useModalScrollLock(showPaymentModal);
  const [paymentTargetOrderId, setPaymentTargetOrderId] = useState('');
  const [localSearchKeyword, setLocalSearchKeyword] = useState('');
  const [localShowSearchBox, setLocalShowSearchBox] = useState(false);
  const [localShowFilterPanel, setLocalShowFilterPanel] = useState(false);
  const [debtViewFilter, setDebtViewFilter] = useState('all');
  const [debtDateFilterMode, setDebtDateFilterMode] = useState('all');
  const [debtFilterDate, setDebtFilterDate] = useState(getTodayString());
  const [debtFilterMonth, setDebtFilterMonth] = useState(getTodayString().slice(0, 7));
  const [debtFilterYear, setDebtFilterYear] = useState(getTodayString().slice(0, 4));
  const [debtCustomStartDate, setDebtCustomStartDate] = useState(getTodayString());
  const [debtCustomEndDate, setDebtCustomEndDate] = useState(getTodayString());
  const [debtTransactionSort, setDebtTransactionSort] = useState('latest');
  const [debtSalesEmpId, setDebtSalesEmpId] = useState('all');
  const [debtShareStatus, setDebtShareStatus] = useState('');
  const [newPayment, setNewPayment] = useState({
    amount: '',
    date: getTodayString(),
    method: 'Chuyển khoản'
  });
  const selectedDebtCustomerSnapshotRef = useRef(null);
  const storedDebtSearch=useSyncExternalStore((searchStore||EMPTY_DEBT_SEARCH_STORE).subscribe,(searchStore||EMPTY_DEBT_SEARCH_STORE).getSnapshot);
  const searchKeyword = searchStore?storedDebtSearch:externalSearchKeyword ?? localSearchKeyword;
  const debtSearchQuery = searchKeyword;
  const setSearchKeyword = setExternalSearchKeyword ?? setLocalSearchKeyword;
  const showSearchBox = externalShowSearchBox ?? localShowSearchBox;
  const setShowSearchBox = setExternalShowSearchBox ?? setLocalShowSearchBox;
  const showFilterPanel = externalShowFilterPanel ?? localShowFilterPanel;
  const setShowFilterPanel = setExternalShowFilterPanel ?? setLocalShowFilterPanel;
  useAppScreenBack(() => {
    if (showPaymentModal) {
      setShowPaymentModal(false);
      return true;
    }
    if (selectedCustomerId) {
      setSelectedCustomerId(null);
      return true;
    }
    return false;
  });
  const canViewAllDebtRecords = Boolean(canViewAllDebt);
  const canViewAssignedDebtRecords = Boolean(canViewAssignedDebt);
  const canRecordCustomerPayment = Boolean(canRecordPayment);
  const canDeleteDebtRecord = Boolean(canDeleteDebt);
  const safeDebtWarehouseImports = useMemo(
    () => (Array.isArray(warehouseImports) ? warehouseImports : []),
    [warehouseImports]
  );

  const sharedDebtLedgerMap = React.useContext(ReconciledLedgerContext);
  const debtLedgerIndex = useMemo(
    () => sharedDebtLedgerMap || buildCustomerReconciledLedgerMap(customers, orders, payments, safeDebtWarehouseImports, expenses),
    [sharedDebtLedgerMap, customers, orders, payments, safeDebtWarehouseImports, expenses]
  );
  const debtDirectoryScope = JSON.stringify([employee?.companyId || '', employee?.id || '',
    canViewAllDebtRecords, canViewAssignedDebtRecords, Boolean(isDriver)]);
  const customerLedgers = useMemo(() => {
    const cached = debtCustomerDirectoryCache([customers, debtLedgerIndex, employees], debtDirectoryScope);
    if (cached.complete) return cached.value;
    const value = customers.map(customer => {
    const ledger = debtLedgerIndex[customer.id];
    const manager = employees.find(emp => emp.id === customer.empId);
    const debtTransactions = [
      ...(ledger.orders || []).map(order => {
        const dateKey = getDateKeyFromAnyValue(order.date || order.createdAt || order.updatedAt || getEntityTimestamp(order));
        return {
          id: `order_${order.id}`,
          type: 'order',
          dateKey,
          timestamp: getEntityTimestamp(order) || (dateKey ? new Date(`${dateKey}T12:00:00`).getTime() : 0)
        };
      }),
      ...(ledger.payments || []).map(payment => {
        const dateKey = getPaymentDateKey(payment) || getDateKeyFromAnyValue(payment.date || payment.createdAt || payment.updatedAt || getEntityTimestamp(payment));
        return {
          id: `payment_${payment.id}`,
          type: 'payment',
          dateKey,
          timestamp: getPaymentTimestamp(payment) || getEntityTimestamp(payment) || (dateKey ? new Date(`${dateKey}T12:00:00`).getTime() : 0)
        };
      })
    ].filter(item => item.dateKey);
    const transactionTimes = debtTransactions.map(item => item.timestamp || 0).filter(Boolean);
    return {
      ...customer,
      ledger,
      debtLimitStatus: buildCustomerDebtLimitStatus(customer, ledger),
      managerName: manager?.name || 'Chưa gán',
      debtTransactions,
      latestDebtTransactionAt: transactionTimes.length ? Math.max(...transactionTimes) : 0,
      oldestDebtTransactionAt: transactionTimes.length ? Math.min(...transactionTimes) : 0
    };
    });
    cached.value = value;
    cached.complete = true;
    return value;
  }, [customers, debtLedgerIndex, employees, debtDirectoryScope]);

  const accessibleCustomers = useMemo(() => customerLedgers.filter(customer => {
    if (customer.isArchived) return false;
    if (canViewAllDebtRecords) return true;
    if (!canViewAssignedDebtRecords) return false;
    if (isDriver) return (customer.allowedDriverIds || []).includes(employee?.id);
    return customer.empId === employee?.id;
  }), [customerLedgers, canViewAllDebtRecords, canViewAssignedDebtRecords, isDriver, employee?.id]);

  const selectedCustomerLive = useMemo(
    () => accessibleCustomers.find(customer => customer.id === selectedCustomerId) || null,
    [accessibleCustomers, selectedCustomerId]
  );

  useEffect(() => {
    if (!selectedCustomerId) {
      selectedDebtCustomerSnapshotRef.current = null;
      return;
    }
    if (selectedCustomerLive) {
      selectedDebtCustomerSnapshotRef.current = selectedCustomerLive;
    }
  }, [selectedCustomerId, selectedCustomerLive]);

  const selectedCustomer = selectedCustomerLive
    || (selectedDebtCustomerSnapshotRef.current?.id === selectedCustomerId ? selectedDebtCustomerSnapshotRef.current : null);

  const debtFilterYears = useMemo(() => {
    const years = new Set([getTodayString().slice(0, 4)]);
    accessibleCustomers.forEach(customer => {
      (customer.debtTransactions || []).forEach(item => {
        if (item.dateKey) years.add(item.dateKey.slice(0, 4));
      });
    });
    return Array.from(years).filter(Boolean).sort((a, b) => b.localeCompare(a));
  }, [accessibleCustomers]);

  const debtManagerOptions = useMemo(() => {
    const managerIds = new Set(accessibleCustomers.map(customer => customer.empId).filter(Boolean));
    return employees
      .filter(emp => managerIds.has(emp.id))
      .sort((a, b) => (a.name || '').localeCompare(b.name || '', 'vi'));
  }, [accessibleCustomers, employees]);

  const debtDateRange = useMemo(() => {
    if (debtDateFilterMode === 'day') {
      const day = getDateKeyFromAnyValue(debtFilterDate) || getTodayString();
      return { start: day, end: day };
    }
    if (debtDateFilterMode === 'month') {
      const monthKey = buildMonthKeyFromDate(debtFilterMonth || getTodayString());
      const [yearText, monthText] = monthKey.split('-');
      const year = parseInt(yearText, 10) || new Date().getFullYear();
      const monthIndex = Math.max(0, Math.min(11, (parseInt(monthText, 10) || 1) - 1));
      const endDate = new Date(year, monthIndex + 1, 0);
      return { start: `${monthKey}-01`, end: toDateInputString(endDate) };
    }
    if (debtDateFilterMode === 'year') {
      const year = `${debtFilterYear || getTodayString().slice(0, 4)}`.slice(0, 4);
      return { start: `${year}-01-01`, end: `${year}-12-31` };
    }
    if (debtDateFilterMode === 'custom') {
      const start = getDateKeyFromAnyValue(debtCustomStartDate);
      const end = getDateKeyFromAnyValue(debtCustomEndDate);
      if (!start && !end) return null;
      const rangeStart = start || '0000-01-01';
      const rangeEnd = end || '9999-12-31';
      return rangeStart <= rangeEnd
        ? { start: rangeStart, end: rangeEnd }
        : { start: rangeEnd, end: rangeStart };
    }
    return null;
  }, [debtDateFilterMode, debtFilterDate, debtFilterMonth, debtFilterYear, debtCustomStartDate, debtCustomEndDate]);

  const resetDebtFilters = () => {
    setDebtViewFilter('all');
    setDebtDateFilterMode('all');
    setDebtFilterDate(getTodayString());
    setDebtFilterMonth(getTodayString().slice(0, 7));
    setDebtFilterYear(getTodayString().slice(0, 4));
    setDebtCustomStartDate(getTodayString());
    setDebtCustomEndDate(getTodayString());
    setDebtTransactionSort('latest');
    setDebtSalesEmpId('all');
    setSearchKeyword('');
  };

  useEffect(() => {
    const targetCustomerId = `${focusCustomerId || ''}`.trim();
    if (!targetCustomerId) return;

    const focusedCustomer = accessibleCustomers.find(customer => customer.id === targetCustomerId);
    if (!focusedCustomer) return;

    selectedDebtCustomerSnapshotRef.current = focusedCustomer;
    setSelectedCustomerId(targetCustomerId);
    setDebtViewFilter('all');
    setSearchKeyword('');
    setShowSearchBox(false);
    setShowFilterPanel(false);
    setShowPaymentModal(false);
    setPaymentTargetOrderId('');
    onFocusCustomerHandled?.();
  }, [focusCustomerId, accessibleCustomers, setSearchKeyword, setShowSearchBox, setShowFilterPanel, onFocusCustomerHandled]);

  useEffect(() => {
    if (
      selectedCustomerId
      && !accessibleCustomers.some(customer => customer.id === selectedCustomerId)
      && selectedDebtCustomerSnapshotRef.current?.id !== selectedCustomerId
    ) {
      setSelectedCustomerId(null);
      setShowPaymentModal(false);
      setPaymentTargetOrderId('');
    }
  }, [selectedCustomerId, accessibleCustomers]);

  useEffect(() => {
    setDebtShareStatus('');
  }, [selectedCustomerId]);

  const debtBaseCustomers = useMemo(() => {
    const baseList = accessibleCustomers
      .filter(customer => {
        if (debtViewFilter === 'debt') return customer.ledger.currentDebt > 0;
        if (debtViewFilter === 'credit') return customer.ledger.creditBalance > 0;
        return customer.ledger.currentDebt > 0 || customer.ledger.creditBalance > 0;
      })
      .filter(customer => debtSalesEmpId === 'all' || customer.empId === debtSalesEmpId)
      .filter(customer => {
        if (!debtDateRange) return true;
        return (customer.debtTransactions || []).some(item => item.dateKey >= debtDateRange.start && item.dateKey <= debtDateRange.end);
      })
      ;
    return baseList;
  }, [accessibleCustomers, debtDateRange, debtSalesEmpId, debtViewFilter]);
  const preparedDebtSearch=usePreparedSearch(debtBaseCustomers,getCustomerSearchFields,debtSearchQuery,undefined,undefined,undefined,{warmup:true});
  const filteredCustomers = useMemo(() => {
    if(hasTokenSearchQuery(debtSearchQuery))return preparedDebtSearch.results;
    return [...debtBaseCustomers].sort((a, b) => {
        if (debtTransactionSort === 'debt_desc' || debtTransactionSort === 'debt_asc') {
          const aDebtAmount = debtViewFilter === 'credit'
            ? a.ledger.creditBalance
            : a.ledger.currentDebt;
          const bDebtAmount = debtViewFilter === 'credit'
            ? b.ledger.creditBalance
            : b.ledger.currentDebt;
          if (aDebtAmount !== bDebtAmount) {
            return debtTransactionSort === 'debt_asc'
              ? aDebtAmount - bDebtAmount
              : bDebtAmount - aDebtAmount;
          }
          const aTime = a.latestDebtTransactionAt || 0;
          const bTime = b.latestDebtTransactionAt || 0;
          if (aTime !== bTime) return bTime - aTime;
        }
        if (debtTransactionSort === 'oldest') {
          const aTime = a.oldestDebtTransactionAt || Number.MAX_SAFE_INTEGER;
          const bTime = b.oldestDebtTransactionAt || Number.MAX_SAFE_INTEGER;
          if (aTime !== bTime) return aTime - bTime;
        } else {
          const aTime = a.latestDebtTransactionAt || 0;
          const bTime = b.latestDebtTransactionAt || 0;
          if (aTime !== bTime) return bTime - aTime;
        }
        if (b.ledger.currentDebt !== a.ledger.currentDebt) return b.ledger.currentDebt - a.ledger.currentDebt;
        return (a.name || '').localeCompare(b.name || '', 'vi');
      });
  }, [debtBaseCustomers, debtSearchQuery, preparedDebtSearch.results, debtTransactionSort, debtViewFilter]);

  const debtCustomerPage = usePagedList(
    filteredCustomers,
    `${debtSearchQuery}|${debtViewFilter}|${debtTransactionSort}|${debtSalesEmpId}|${debtDateRange?.start || ''}|${debtDateRange?.end || ''}`
  );
  const completedDebtPageRef=useRef(null);
  const retainedDebtPage=preparedDebtSearch.pending
    &&completedDebtPageRef.current?.scope===debtDirectoryScope
    &&completedDebtPageRef.current?.base===debtBaseCustomers
    ?completedDebtPageRef.current.pagination:null;
  const displayedDebtPage=retainedDebtPage||debtCustomerPage;
  useEffect(()=>{
    if(!preparedDebtSearch.pending&&!preparedDebtSearch.error)
      completedDebtPageRef.current={scope:debtDirectoryScope,base:debtBaseCustomers,pagination:debtCustomerPage};
  },[preparedDebtSearch.pending,preparedDebtSearch.error,debtDirectoryScope,debtBaseCustomers,debtCustomerPage]);

  const debtOverviewCustomers = useMemo(
    () => accessibleCustomers.filter(customer => debtSalesEmpId === 'all' || customer.empId === debtSalesEmpId),
    [accessibleCustomers, debtSalesEmpId]
  );

  const debtOverviewSummary = useMemo(() => debtOverviewCustomers.reduce((acc, customer) => {
    const currentDebt = Math.max(0, roundMoneyValue(customer.ledger?.currentDebt || 0));
    const creditBalance = Math.max(0, roundMoneyValue(customer.ledger?.creditBalance || 0));
    acc.totalDebt += currentDebt;
    acc.totalCredit += creditBalance;
    if (currentDebt > 0) acc.debtCustomerCount += 1;
    if (creditBalance > 0) acc.creditCustomerCount += 1;
    return acc;
  }, { totalDebt: 0, totalCredit: 0, debtCustomerCount: 0, creditCustomerCount: 0 }), [debtOverviewCustomers]);

  const resetPaymentDraft = () => {
    setShowPaymentModal(false);
    setPaymentTargetOrderId('');
    setNewPayment({
      amount: '',
      date: getTodayString(),
      method: 'Chuyển khoản'
    });
  };

  const openDebtCustomerDetail = (customer) => {
    if (!customer?.id) return;
    selectedDebtCustomerSnapshotRef.current = customer;
    setSelectedCustomerId(customer.id);
  };

  const openPaymentModal = (order = null) => {
    const repayment = !order && selectedCustomer?.ledger?.creditBalance > 0;
    if (repayment ? !canRecordRepayment : !canRecordCustomerPayment) return;
    setDebtPaymentStatus('');
    const dueAmount = Math.max(0, parseLooseMoneyValue(order?.outstandingAmount ?? 0));
    setPaymentTargetOrderId(order?.id || '');
    setNewPayment({
      clientMutationId: `p_${crypto.randomUUID()}`,
      kind: repayment ? 'repayment' : 'receipt',
      amount: repayment ? String(selectedCustomer.ledger.creditBalance) : dueAmount > 0 ? String(dueAmount) : '',
      date: getTodayString(),
      method: 'Chuyển khoản'
    });
    setShowPaymentModal(true);
  };

  const handlePaymentSubmit = async (e) => {
    e.preventDefault();
    if (debtPaymentSubmitRef.current) return;
    const repayment = newPayment.kind === 'repayment';
    if (!selectedCustomer || (repayment ? !canRecordRepayment : !canRecordCustomerPayment)) return;

    const paymentAmount = parseLooseMoneyValue(newPayment.amount);
    if (!Number.isFinite(paymentAmount) || paymentAmount <= 0) {
      window.alert('Vui lòng nhập số tiền lớn hơn 0.');
      return;
    }
    if (repayment && paymentAmount > (selectedCustomer.ledger?.creditBalance || 0)) {
      setDebtPaymentStatus('Số tiền chi không được vượt khoản công ty còn nợ khách.');
      return;
    }

    const sourceType = newPayment.method === 'Tiền mặt'
      ? (isDriver ? 'driver_cash' : 'accounting_cash')
      : 'customer_transfer';
    const collectorName = employee?.name || employee?.displayName || 'Người thu';
    const sourceLabel = newPayment.method === 'Tiền mặt' ? 'Thu tiền mặt' : 'Khách chuyển khoản';
    const matchedOrder = paymentTargetOrderId
      ? (selectedCustomer.ledger?.orders || []).find(order => order.id === paymentTargetOrderId)
      : null;
    const matchedOrderCode = matchedOrder ? getLedgerOrderDisplayCode(matchedOrder) : '';

    try {
      debtPaymentSubmitRef.current = true;
      setIsSavingDebtPayment(true);
      setDebtPaymentStatus('');
      if (repayment) {
        const result = await onAddRepayment({
          clientMutationId: newPayment.clientMutationId,
          customerId: selectedCustomer.id,
          amount: paymentAmount,
          date: newPayment.date,
          method: newPayment.method,
          category: 'Chi trả nợ khách hàng',
          sourceType: 'customer_debt_repayment',
          note: `Chi trả nợ khách hàng ${selectedCustomer.name || ''}`,
          paidByName: employee?.name || employee?.displayName || '',
        });
        if (!result) throw new Error('Chưa nhận được xác nhận tiếp nhận khoản chi.');
        setDebtPaymentStatus(result.queued ? 'Đã lưu tạm khoản chi trả nợ. Đang đồng bộ, chưa xác nhận từ máy chủ.' : 'Đã ghi nhận khoản chi trả nợ.');
        resetPaymentDraft();
        return;
      }
      const result = await onAddPayment({
        clientMutationId: newPayment.clientMutationId,
        customerId: selectedCustomer.id,
        amount: paymentAmount,
        date: newPayment.date,
        method: newPayment.method,
        note: matchedOrderCode ? `Thu nợ ${matchedOrderCode}` : 'Thu công nợ',
        bankContent: matchedOrderCode ? `TT ${matchedOrderCode}` : '',
        referenceCode: matchedOrderCode,
        matchedOrderId: matchedOrder?.id || '',
        matchedOrderCode,
        sourceOrderId: matchedOrder?.id || '',
        allocateOldestFirst: true,
        allocationMode: 'oldest_first',
        sourceType: matchedOrder ? 'debt_order_payment' : sourceType,
        sourceLabel: matchedOrder
          ? (newPayment.method === 'Tiền mặt' ? 'Thu nợ tiền mặt tại sổ nợ' : 'Thu nợ chuyển khoản tại sổ nợ')
          : sourceLabel,
        empId: employee?.id || '',
        createdByEmpId: employee?.id || '',
        collectorEmpId: employee?.id || '',
        collectedByEmpId: employee?.id || '',
        collectorName,
        collectedByName: collectorName
      });

      if (!result) throw new Error('Chưa nhận được xác nhận tiếp nhận khoản thu.');
      setDebtPaymentStatus(result.queued ? 'Đã lưu tạm khoản thu. Đang đồng bộ, chưa xác nhận từ máy chủ.' : 'Đã ghi nhận khoản thu.');
      resetPaymentDraft();
    } catch (error) {
      const friendlyMessage = getFriendlyFirebaseErrorMessage(error, repayment ? 'Không thể ghi nhận khoản chi trả nợ. Vui lòng thử lại.' : 'Không thể ghi nhận khoản thu. Vui lòng thử lại.');
      setDebtPaymentStatus(friendlyMessage);
    } finally {
      debtPaymentSubmitRef.current = false;
      setIsSavingDebtPayment(false);
    }
  };

  const resolveDebtShareStatusMessage = (result, channel) => {
    if (result.status === 'shared') {
      if (channel === 'native') return 'Đã mở bảng chia sẻ của máy. Bạn có thể chọn Zalo, Facebook, Messenger hoặc ứng dụng khác để gửi ngay.';
      return `Đã mở bảng chia sẻ. Hãy chọn ${getShareChannelLabel(channel)} nếu máy đã cài ứng dụng đó.`;
    }
    if (result.status === 'copied') {
      return `Nội dung công nợ đã được sao chép. Bạn có thể dán vào ${getShareChannelLabel(channel)} hoặc tin nhắn để gửi cho khách.`;
    }
    if (result.status === 'cancelled') return 'Bạn đã đóng bảng chia sẻ.';
    return 'Thiết bị này chưa hỗ trợ chia sẻ trực tiếp. Bạn có thể dùng nút sao chép hoặc lưu file.';
  };

  const buildDebtShareText = (customer) => {
    if (!customer) return '';
    const { ledger } = customer;

    const lines = [
      `THÔNG BÁO CÔNG NỢ - ${customer.name || 'Khách hàng'}`,
      `Ngày cập nhật: ${formatDateTimeLabel(new Date())}`,
      `Số điện thoại: ${customer.phone || 'Chưa có'}`,
      `Địa chỉ: ${customer.address || 'Chưa có'}`,
      `Nhân viên phụ trách: ${customer.managerName || 'Chưa gán'}`,
      '',
      `Tổng doanh thu: ${formatCurrency(ledger.totalRevenue || 0)} đ`,
      `Đã thanh toán: ${formatCurrency(ledger.totalPaid || 0)} đ`,
      `Còn nợ hiện tại: ${formatCurrency(ledger.currentDebt || 0)} đ`,
      `Nợ khách: ${formatCurrency(ledger.creditBalance || 0)} đ`,
      '',
      'Danh sách đơn hàng:'
    ];

    const debtShareOrders = sortLedgerOrdersNewestFirst(ledger.orders || []);

    if (debtShareOrders.length === 0) {
      lines.push('- Chưa có đơn hàng nào.');
    } else {
      debtShareOrders.forEach((order, index) => {
        lines.push(`${index + 1}. ${getLedgerOrderDisplayCode(order)} - ${formatDateLabel(order.date)} - Tổng ${formatCurrency(order.amount || 0)} đ - Còn nợ ${formatCurrency(order.outstandingAmount || 0)} đ`);
      });
    }

    lines.push('', 'Lịch sử thanh toán:');
    if ((ledger.payments || []).length === 0) {
      lines.push('- Chưa có khoản thu nào.');
    } else {
      ledger.payments.forEach((payment, index) => {
        const collectorLabel = getPaymentCollectorLabel(payment, employees);
        lines.push(`${index + 1}. ${formatDateLabel(getPaymentDateKey(payment) || payment.date)} - ${getPaymentMethodLabel(payment)}${collectorLabel ? ` - Người thu: ${collectorLabel}` : ''} - Thu ${formatCurrency(payment.amount || 0)} đ - Đã trừ nợ ${formatCurrency(payment.appliedAmount || 0)} đ`);
      });
    }

    return lines.join('\n');
  };

  const buildDebtShareHtml = (customer) => {
    const { ledger } = customer || {};
    const orderRows = sortLedgerOrdersNewestFirst(ledger?.orders || []).map((order) => `
      <tr>
        <td style="padding:10px;border-bottom:1px solid #e5e7eb;">${escapeHtml(getLedgerOrderDisplayCode(order))}</td>
        <td style="padding:10px;border-bottom:1px solid #e5e7eb;">${escapeHtml(formatDateLabel(order.date))}</td>
        <td style="padding:10px;border-bottom:1px solid #e5e7eb;text-align:right;">${escapeHtml(formatCurrency(order.amount || 0))} đ</td>
        <td style="padding:10px;border-bottom:1px solid #e5e7eb;text-align:right;">${escapeHtml(formatCurrency(order.outstandingAmount || 0))} đ</td>
      </tr>
    `).join('');

    const paymentRows = (ledger?.payments || []).map((payment) => `
      <tr>
        <td style="padding:10px;border-bottom:1px solid #eef2f7;">${escapeHtml(formatDateLabel(getPaymentDateKey(payment) || payment.date))}</td>
        <td style="padding:10px;border-bottom:1px solid #eef2f7;">${escapeHtml(getPaymentMethodLabel(payment))}</td>
        <td style="padding:10px;border-bottom:1px solid #eef2f7;">${escapeHtml(getPaymentCollectorLabel(payment, employees) || 'Chưa rõ')}</td>
        <td style="padding:10px;border-bottom:1px solid #eef2f7;text-align:right;">${escapeHtml(formatCurrency(payment.amount || 0))} đ</td>
        <td style="padding:10px;border-bottom:1px solid #eef2f7;text-align:right;">${escapeHtml(formatCurrency(payment.appliedAmount || 0))} đ</td>
      </tr>
    `).join('');

    return `
      <!doctype html>
      <html lang="vi">
        <head>
          <meta charset="utf-8" />
          <title>${escapeHtml(customer?.name || 'Công nợ khách hàng')}</title>
        </head>
        <body style="font-family: Arial, sans-serif; background:#f3f4f6; padding:24px; color:#111827;">
          <div style="max-width:860px; margin:0 auto; background:#ffffff; border-radius:20px; padding:24px; border:1px solid #e5e7eb;">
            <h1 style="margin:0 0 8px; font-size:28px;">Thông báo công nợ</h1>
            <p style="margin:0 0 16px; color:#6b7280;">Khách hàng: ${escapeHtml(customer?.name || 'Khách hàng')} • Cập nhật: ${escapeHtml(formatDateTimeLabel(new Date()))}</p>
            <div style="margin-top:20px; background:#f9fafb; border-radius:16px; padding:16px;">
              <p style="margin:0 0 8px;">Tổng doanh thu: <strong>${escapeHtml(formatCurrency(ledger?.totalRevenue || 0))} đ</strong></p>
              <p style="margin:0 0 8px;">Đã thanh toán: <strong>${escapeHtml(formatCurrency(ledger?.totalPaid || 0))} đ</strong></p>
              <p style="margin:0 0 8px;">Còn nợ hiện tại: <strong>${escapeHtml(formatCurrency(ledger?.currentDebt || 0))} đ</strong></p>
              <p style="margin:0;">Nợ khách: <strong>${escapeHtml(formatCurrency(ledger?.creditBalance || 0))} đ</strong></p>
            </div>
            <h2 style="margin:24px 0 12px; font-size:18px;">Đơn hàng và công nợ</h2>
            <table style="width:100%; border-collapse:collapse;">
              <thead style="background:#f9fafb;">
                <tr>
                  <th style="padding:10px;text-align:left;">Mã đơn</th>
                  <th style="padding:10px;text-align:left;">Ngày</th>
                  <th style="padding:10px;text-align:right;">Tổng đơn</th>
                  <th style="padding:10px;text-align:right;">Còn nợ</th>
                </tr>
              </thead>
              <tbody>${orderRows || '<tr><td colspan="4" style="padding:12px;text-align:center;color:#6b7280;">Chưa có đơn hàng nào</td></tr>'}</tbody>
            </table>
            <h2 style="margin:24px 0 12px; font-size:18px;">Lịch sử thanh toán</h2>
            <table style="width:100%; border-collapse:collapse;">
              <thead style="background:#f9fafb;">
                <tr>
                  <th style="padding:10px;text-align:left;">Ngày</th>
                  <th style="padding:10px;text-align:left;">Phương thức</th>
                  <th style="padding:10px;text-align:left;">Người thu</th>
                  <th style="padding:10px;text-align:right;">Số tiền thu</th>
                  <th style="padding:10px;text-align:right;">Đã trừ nợ</th>
                </tr>
              </thead>
              <tbody>${paymentRows || '<tr><td colspan="5" style="padding:12px;text-align:center;color:#6b7280;">Chưa có khoản thu nào</td></tr>'}</tbody>
            </table>
          </div>
        </body>
      </html>
    `;
  };

  const handleShareDebt = async (channel = 'native') => {
    if (!selectedCustomer) return;
    const result = await shareTextContent({
      title: `Công nợ - ${selectedCustomer.name || 'Khách hàng'}`,
      text: buildDebtShareText(selectedCustomer),
      dialogTitle: channel === 'native' ? 'Chia sẻ công nợ' : `Chia sẻ qua ${getShareChannelLabel(channel)}`
    });
    setDebtShareStatus(resolveDebtShareStatusMessage(result, channel));
  };

  const handleCopyDebt = async () => {
    if (!selectedCustomer) return;
    const copied = await copyTextToClipboard(buildDebtShareText(selectedCustomer));
    setDebtShareStatus(copied ? 'Đã sao chép thông tin công nợ. Bạn có thể dán vào Zalo, Facebook, Messenger hoặc email.' : 'Không thể sao chép thông tin công nợ trên thiết bị này.');
  };

  const handleDownloadDebt = async () => {
    if (!selectedCustomer) return;
    const safeName = (selectedCustomer.name || 'khach-hang').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'khach-hang';
    const result = await saveContentFile(`cong-no-${safeName}.html`, buildDebtShareHtml(selectedCustomer), 'text/html;charset=utf-8');
    if (result.status === 'saved') {
      setDebtShareStatus('Đã lưu file công nợ vào bộ nhớ máy để bạn xem lại hoặc gửi tiếp cho khách.');
      return;
    }
    if (result.status === 'downloaded') {
      setDebtShareStatus('Đã tải file công nợ về máy để bạn lưu hoặc gửi tiếp cho khách.');
      return;
    }
    setDebtShareStatus('Không thể lưu file trên thiết bị này. Bạn vẫn có thể dùng nút chia sẻ hoặc sao chép.');
  };

  if (selectedCustomer) {
    const { ledger } = selectedCustomer;
    const debtOrdersInRange = (ledger.orders || []).filter(order => {
      if (!debtDateRange) return true;
      const orderDateKey = getDateKeyFromAnyValue(order.date || order.createdAt || order.updatedAt || getEntityTimestamp(order));
      return orderDateKey >= debtDateRange.start && orderDateKey <= debtDateRange.end;
    });
    const displayDebtOrders = debtTransactionSort === 'oldest'
      ? [...debtOrdersInRange].sort(compareLedgerItems)
      : sortLedgerOrdersNewestFirst(debtOrdersInRange);
    const paymentLookup = new Map((ledger.payments || []).map(payment => [payment.id, payment]));
    const creditPayments = (ledger.payments || []).filter(payment => (payment.overpaidAmount || 0) > 0);
    const paymentTargetOrder = paymentTargetOrderId
      ? (ledger.orders || []).find(order => order.id === paymentTargetOrderId)
      : null;

    return (
      <div className="premium-data-module premium-debt-module premium-debt-detail space-y-4 animate-in fade-in pb-16">
        {debtPaymentStatus && !showPaymentModal && <p role="status" className="text-sm text-slate-600">{debtPaymentStatus}</p>}
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex items-start justify-between gap-3">
            <div>
              <h2 className="font-bold text-xl text-gray-800">{selectedCustomer.name}</h2>
              <p className="text-sm text-gray-500 mt-1">{selectedCustomer.phone || 'Chưa có số điện thoại'} • {selectedCustomer.managerName}</p>
              <p className="text-sm text-gray-500 mt-1">{selectedCustomer.address || 'Chưa có địa chỉ'}</p>
            </div>
            <button type="button" disabled={!ledger.creditBalance} onClick={() => { setSelectedCustomerId(null); setDebtViewFilter('credit'); setSearchKeyword(''); setDebtDateFilterMode('all'); }} className={`px-3 py-2 rounded-xl text-right min-w-[132px] ${ledger.currentDebt > 0 ? 'bg-red-50 text-red-600' : ledger.creditBalance > 0 ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'}`}>
              <p className="text-[10px] font-bold uppercase tracking-wide">{ledger.currentDebt > 0 ? 'Còn phải thu' : ledger.creditBalance > 0 ? 'Nợ khách' : 'Đã cân bằng'}</p>
              <p className="text-lg font-black">{formatCurrency(ledger.currentDebt > 0 ? ledger.currentDebt : ledger.creditBalance)} đ</p>
            </button>
          </div>

          <div className="grid grid-cols-2 gap-3 mt-4">
            <div className="bg-white border border-gray-100 rounded-xl p-3">
              <p className="text-[10px] uppercase font-bold text-gray-500 mb-1">Tổng doanh thu</p>
              <p className="text-lg font-black text-gray-800">{formatCurrency(ledger.totalRevenue)} đ</p>
            </div>
            <div className="bg-white border border-gray-100 rounded-xl p-3">
              <p className="text-[10px] uppercase font-bold text-gray-500 mb-1">Đã thanh toán</p>
              <p className="text-lg font-black text-emerald-600">{formatCurrency(ledger.totalPaid)} đ</p>
            </div>
          </div>

          {selectedCustomer.debtLimitStatus?.enabled && (
            <div className={`mt-4 rounded-2xl border px-4 py-3 ${
              selectedCustomer.debtLimitStatus.exceeded
                ? 'border-rose-200 bg-rose-50 text-rose-700'
                : 'border-emerald-100 bg-emerald-50 text-emerald-700'
            }`}>
              <p className="text-[11px] font-black uppercase tracking-wide">{selectedCustomer.debtLimitStatus.exceeded ? 'Vượt hạn mức công nợ' : 'Hạn mức công nợ'}</p>
              <p className="mt-1 text-sm font-bold leading-5">{selectedCustomer.debtLimitStatus.message}</p>
            </div>
          )}

          <div className="mt-4 grid grid-cols-[minmax(0,1fr)_auto] items-stretch gap-2" data-debt-actions="true">
          {(ledger.creditBalance > 0 ? canRecordRepayment : canRecordCustomerPayment) ? (
            <button type="button" onClick={() => openPaymentModal()} className="min-h-12 min-w-0 px-3 py-2 rounded-lg text-sm font-bold text-white flex justify-center items-center gap-2 bg-blue-600 hover:bg-blue-700">
              <Wallet size={18} className="shrink-0"/> <span>{ledger.creditBalance > 0 ? 'Ghi nhận khoản chi trả nợ' : 'Ghi nhận khoản thu'}</span>
            </button>
          ) : (
            <div className="min-w-0 bg-blue-50 border border-blue-100 text-blue-700 rounded-lg p-3 text-sm leading-relaxed">
              {ledger.creditBalance > 0 ? 'Tài khoản này chưa được cấp quyền ghi nhận khoản chi. Hãy báo kế toán hoặc chủ doanh nghiệp xác nhận.' : 'Tài khoản này chưa được cấp quyền ghi nhận thu nợ. Nếu đã nhận tiền, hãy báo kế toán hoặc chủ doanh nghiệp xác nhận trên hệ thống.'}
            </div>
          )}
          <DebtBalanceShareButton key={selectedCustomer.id} customer={selectedCustomer} shareText={shareTextContent} />
          </div>
        </div>

        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
          <div className="px-4 py-3 border-b border-gray-100 flex items-center justify-between gap-3">
            <div>
              <h3 className="font-bold text-gray-800">Đơn hàng, công nợ và thu tiền</h3>
              <p className="text-[11px] text-gray-400 mt-0.5">Khoản thu được gộp ngay trong từng đơn để dễ đối soát.</p>
            </div>
            <span className="shrink-0 text-xs text-gray-400">{displayDebtOrders.length} đơn</span>
          </div>
          <div className="divide-y divide-gray-50">
            {displayDebtOrders.length === 0 && <p className="p-4 text-center text-sm text-gray-400">Khách hàng này chưa có đơn hàng.</p>}
            {displayDebtOrders.map(order => {
              const orderPaymentAllocations = (order.allocations || [])
                .map(allocation => ({
                  ...allocation,
                  payment: paymentLookup.get(allocation.paymentId)
                }))
                .filter(allocation => allocation.amount > 0);

              return (
                <div key={order.id} className="p-4">
                  <div className="space-y-2.5">
                    <div className="flex items-center justify-between gap-3">
                      <div className="min-w-0">
                        <h4 className="truncate font-black text-gray-800">{getLedgerOrderDisplayCode(order)}</h4>
                        <p className="mt-0.5 text-xs font-semibold text-gray-500">{new Date(order.date).toLocaleDateString('vi-VN')}</p>
                      </div>
                      {canRecordCustomerPayment && order.outstandingAmount > 0 && (
                        <button
                          type="button"
                          onClick={() => openPaymentModal(order)}
                          className="shrink-0 inline-flex items-center justify-center gap-1 rounded-xl bg-blue-600 px-3 py-2 text-[11px] font-black text-white shadow-sm active:scale-[0.98]"
                        >
                          <Wallet size={13} /> Thu nợ
                        </button>
                      )}
                    </div>
                    <div className="grid grid-cols-3 gap-1.5 text-center text-[10px] leading-tight">
                      <div className="flex min-h-[58px] flex-col items-center justify-center rounded-xl bg-gray-50 px-1.5 py-2">
                        <p className="font-black uppercase text-gray-400">Số tiền</p>
                        <p className="mt-1 break-all font-black text-gray-800">{formatCurrency(order.amount)} đ</p>
                      </div>
                      <div className="flex min-h-[58px] flex-col items-center justify-center rounded-xl bg-emerald-50 px-1.5 py-2">
                        <p className="font-black uppercase text-emerald-500">Đã thu</p>
                        <p className="mt-1 break-all font-black text-emerald-700">{formatCurrency(order.appliedAmount || 0)} đ</p>
                      </div>
                      <div className={`flex min-h-[58px] flex-col items-center justify-center rounded-xl px-1.5 py-2 ${order.outstandingAmount > 0 ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-700'}`}>
                        <p className="font-black uppercase">{order.outstandingAmount > 0 ? 'Còn nợ' : 'Hết nợ'}</p>
                        <p className="mt-1 break-all font-black">{order.outstandingAmount > 0 ? `${formatCurrency(order.outstandingAmount)} đ` : '0 đ'}</p>
                      </div>
                    </div>
                  </div>

                  <div className="mt-3 rounded-2xl bg-slate-50 px-3 py-2">
                    {orderPaymentAllocations.length > 0 ? (
                      <div className="space-y-1.5">
                        {orderPaymentAllocations.map((allocation, index) => {
                          const collectorLabel = getPaymentCollectorLabel(allocation.payment || {}, employees);
                          return (
                            <div key={`${order.id}_${allocation.paymentId || index}`} className="flex items-center justify-between gap-2 text-[11px]">
                              <span className="min-w-0 truncate font-semibold text-slate-500">
                                Thu {formatDateLabel(getPaymentDateKey(allocation.payment || {}) || allocation.date)} • {getPaymentMethodLabel(allocation.payment || {})}{collectorLabel ? ` • ${collectorLabel}` : ''}
                              </span>
                              <span className="shrink-0 font-black text-emerald-600">+{formatCurrency(allocation.amount)} đ</span>
                            </div>
                          );
                        })}
                      </div>
                    ) : (
                      <p className="text-[11px] font-semibold text-slate-400">Chưa có khoản thu gắn với đơn này.</p>
                    )}
                    <div className="flex flex-wrap gap-2 mt-2">
                      {order.creditApplied > 0 && <span className="text-[11px] px-2 py-1 rounded-full font-bold bg-blue-50 text-blue-600">Đã trừ từ tiền dư {formatCurrency(order.creditApplied)} đ</span>}
                      {order.appliedAmount > order.creditApplied && <span className="text-[11px] px-2 py-1 rounded-full font-bold bg-emerald-50 text-emerald-600">Đã thanh toán {formatCurrency(order.appliedAmount)} đ</span>}
                    </div>
                  </div>
                </div>
              );
            })}
            {creditPayments.length > 0 && (
              <div className="bg-blue-50/60 p-4">
                <p className="text-xs font-black uppercase tracking-wide text-blue-700">Tiền dư / khoản thu chưa trừ đơn</p>
                <div className="mt-2 space-y-1.5">
                  {creditPayments.map(payment => {
                    const collectorLabel = getPaymentCollectorLabel(payment, employees);
                    return (
                      <div key={payment.id} className="flex items-center justify-between gap-2 text-xs">
                        <span className="min-w-0 truncate font-semibold text-blue-700">
                          {formatDateLabel(getPaymentDateKey(payment) || payment.date)} • {getPaymentMethodLabel(payment)}{collectorLabel ? ` • ${collectorLabel}` : ''} • {getPaymentSourceLabel(payment)}
                        </span>
                        <span className="shrink-0 font-black text-blue-700">+{formatCurrency(payment.overpaidAmount || 0)} đ</span>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="hidden">
        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
          <div className="px-4 py-3 border-b border-gray-100 flex items-center justify-between">
            <h3 className="font-bold text-gray-800">Đơn hàng và công nợ</h3>
            <span className="text-xs text-gray-400">{displayDebtOrders.length} đơn</span>
          </div>
          <div className="divide-y divide-gray-50">
            {displayDebtOrders.length === 0 && <p className="p-4 text-center text-sm text-gray-400">Khách hàng này chưa có đơn hàng.</p>}
            {displayDebtOrders.map(order => (
              <div key={order.id} className="p-4">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <h4 className="font-bold text-gray-800">{getLedgerOrderDisplayCode(order)}</h4>
                    <p className="text-xs text-gray-500 mt-1">{new Date(order.date).toLocaleDateString('vi-VN')}</p>
                  </div>
                  <div className="text-right">
                    <p className="font-black text-gray-800">{formatCurrency(order.amount)} đ</p>
                    <p className={`text-[11px] mt-1 font-bold ${order.outstandingAmount > 0 ? 'text-red-600' : 'text-emerald-600'}`}>{order.outstandingAmount > 0 ? `Còn nợ ${formatCurrency(order.outstandingAmount)} đ` : 'Đã thanh toán hết'}</p>
                  </div>
                </div>
                <div className="flex flex-wrap gap-2 mt-2">
                  {order.creditApplied > 0 && <span className="text-[11px] px-2 py-1 rounded-full font-bold bg-blue-50 text-blue-600">Đã trừ từ tiền dư {formatCurrency(order.creditApplied)} đ</span>}
                  {order.appliedAmount > order.creditApplied && <span className="text-[11px] px-2 py-1 rounded-full font-bold bg-emerald-50 text-emerald-600">Đã thanh toán {formatCurrency(order.appliedAmount)} đ</span>}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
          <div className="px-4 py-3 border-b border-gray-100 flex items-center justify-between">
            <h3 className="font-bold text-gray-800">Lịch sử thu tiền</h3>
            <span className="text-xs text-gray-400">{ledger.payments.length} lần thu</span>
          </div>
          <div className="divide-y divide-gray-50">
            {ledger.payments.length === 0 && <p className="p-4 text-center text-sm text-gray-400">Chưa có khoản thu nào.</p>}
            {ledger.payments.map(payment => (
              <div key={payment.id} className="p-4 relative">
                {canDeleteDebtRecord && onDeletePayment && (
                  <button onClick={() => { if (window.confirm('Xóa phiếu thu này?')) onDeletePayment(payment.id); }} className="absolute top-3 right-3 text-gray-300 hover:text-red-500">
                    <Trash2 size={14} />
                  </button>
                )}
                <div className="pr-6">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <p className="font-semibold text-gray-800">{payment.note || 'Thu công nợ'}</p>
                      <p className="text-xs text-gray-500 mt-1">{formatDateLabel(getPaymentDateKey(payment) || payment.date)} • {getPaymentMethodLabel(payment)} • {getPaymentSourceLabel(payment)}</p>
                    </div>
                    <p className="font-black text-emerald-600">+{formatCurrency(payment.amount)} đ</p>
                  </div>
                  <div className="flex flex-wrap gap-2 mt-2">
                    <span className="text-[11px] px-2 py-1 rounded-full font-bold bg-emerald-50 text-emerald-600">Đã trừ nợ {formatCurrency(payment.appliedAmount || 0)} đ</span>
                    {(payment.overpaidAmount || 0) > 0 && <span className="text-[11px] px-2 py-1 rounded-full font-bold bg-blue-50 text-blue-600">Khách dư {formatCurrency(payment.overpaidAmount)} đ</span>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        </div>

        {(ledger.repayments || []).length > 0 && (
          <section className="border-t border-gray-200 py-4" aria-label="Lịch sử chi trả nợ">
            <h3 className="font-bold text-gray-800">Chi trả nợ khách hàng</h3>
            {ledger.repayments.map(item => <div key={item.id} className="flex justify-between gap-3 border-b border-gray-100 py-3 text-sm">
              <span>{formatDateLabel(item.date)} · {item.method}<br />{item.paidByName}</span>
              <strong className="text-orange-700">-{formatCurrency(item.amount)} đ</strong>
            </div>)}
          </section>
        )}

        {showPaymentModal && (newPayment.kind === 'repayment' ? canRecordRepayment : canRecordCustomerPayment) && (
          <div className="hd-modal-layer fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" data-hd-modal-root="true">
            <div className="hd-modal-surface bg-white rounded-2xl p-5 w-full max-w-sm" role="dialog" aria-modal="true" aria-label="Ghi nhận thanh toán">
              <h3 className="font-bold text-lg mb-1">{newPayment.kind === 'repayment' ? 'Ghi nhận khoản chi trả nợ' : paymentTargetOrder ? 'Thu nợ đơn hàng' : 'Ghi nhận thanh toán'}</h3>
              {paymentTargetOrder && (
                <p className="mb-4 text-xs font-semibold text-blue-600">
                  {getLedgerOrderDisplayCode(paymentTargetOrder)} • Còn nợ {formatCurrency(paymentTargetOrder.outstandingAmount || 0)} đ
                </p>
              )}
              {!paymentTargetOrder && <div className="mb-4" />}
              <form onSubmit={handlePaymentSubmit} className="min-h-0 flex flex-col">
                <div className="hd-modal-body space-y-3">
                <input required type="tel" value={formatInputCurrency(newPayment.amount)} onChange={e=>setNewPayment({...newPayment, amount: parseInputCurrency(e.target.value)})} className="w-full border p-3 rounded-xl text-lg font-bold text-emerald-600 outline-none" placeholder="Số tiền (VNĐ)" />
                <select value={newPayment.method} onChange={e=>setNewPayment({...newPayment, method: e.target.value})} className="w-full border p-3 rounded-xl text-sm bg-white outline-none">
                  <option value="Tiền mặt">Tiền mặt</option>
                  <option value="Chuyển khoản">Chuyển khoản</option>
                </select>
                <input type="date" value={newPayment.date} onChange={e=>setNewPayment({...newPayment, date: e.target.value})} className="w-full border p-3 rounded-xl text-sm bg-white outline-none" />
                <div className="rounded-xl border border-emerald-100 bg-emerald-50 px-3 py-3">
                  <p className="text-[10px] font-black uppercase tracking-wide text-emerald-600">{newPayment.kind === 'repayment' ? 'Người chi' : 'Người thu'}</p>
                  <p className="mt-1 text-sm font-black text-emerald-800">{employee?.name || employee?.displayName || 'Tài khoản đang đăng nhập'}</p>
                </div>
                {debtPaymentStatus && <p role="status" className="text-sm text-rose-700">{debtPaymentStatus}</p>}
                </div>
                <div className="hd-modal-actions flex gap-2 mt-4">
                  <button type="button" disabled={isSavingDebtPayment} onClick={resetPaymentDraft} className="flex-1 bg-gray-100 py-3 rounded-xl text-gray-700 font-bold">Hủy</button>
                  <button type="submit" disabled={isSavingDebtPayment} className="flex-1 bg-emerald-500 text-white py-3 rounded-xl font-bold">{isSavingDebtPayment ? 'Đang lưu...' : newPayment.kind === 'repayment' ? 'Xác nhận chi trả nợ' : 'Xác nhận thu'}</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="premium-data-module premium-debt-module space-y-4 animate-in fade-in pb-16">
      {(canViewAllDebtRecords || accessibleCustomers.length > 0) && (
        <div className="-mt-4 -mx-4 grid grid-cols-2 overflow-hidden border-y border-slate-100 shadow-sm">
          <button type="button" onClick={() => { setDebtViewFilter('debt'); setSearchKeyword(''); setDebtDateFilterMode('all'); }} aria-pressed={debtViewFilter === 'debt'} className="flex min-h-[96px] flex-col justify-center bg-gradient-to-r from-rose-600 to-orange-500 px-4 py-3 text-left text-white">
            <div className="flex items-center justify-between gap-2 text-[11px] font-bold leading-tight">
              <span>Khách nợ</span>
              <span className="whitespace-nowrap text-white/85">{debtOverviewSummary.debtCustomerCount} khách</span>
            </div>
            <p className="mt-2 w-full whitespace-nowrap text-center text-[12px] font-black leading-tight">{formatCurrency(debtOverviewSummary.totalDebt)} đ</p>
          </button>
          <button type="button" onClick={() => { setDebtViewFilter('credit'); setSearchKeyword(''); setDebtDateFilterMode('all'); }} aria-pressed={debtViewFilter === 'credit'} className="flex min-h-[96px] flex-col items-end justify-center bg-gradient-to-l from-sky-600 to-cyan-500 px-4 py-3 text-right text-white">
            <div className="flex w-full items-center justify-between gap-2 text-[11px] font-bold leading-tight">
              <span className="whitespace-nowrap text-white/85">{debtOverviewSummary.creditCustomerCount} khách</span>
              <span>Nợ khách</span>
            </div>
            <p className="mt-2 w-full whitespace-nowrap text-center text-[12px] font-black leading-tight">{formatCurrency(debtOverviewSummary.totalCredit)} đ</p>
          </button>
        </div>
      )}

      {showFilterPanel && (
        <div className="premium-data-toolbar bg-white rounded-2xl shadow-sm border border-gray-100 p-4 space-y-3">
          <div className="space-y-3">
            <div className="grid grid-cols-3 gap-2">
              <button type="button" onClick={() => setDebtViewFilter('all')} className={`rounded-xl border px-3 py-3 text-xs font-bold transition-colors ${debtViewFilter === 'all' ? 'border-emerald-200 bg-emerald-50 text-emerald-700' : 'border-gray-200 bg-white text-gray-600 hover:bg-gray-50'}`}>Tất cả</button>
              <button type="button" onClick={() => setDebtViewFilter('debt')} className={`rounded-xl border px-3 py-3 text-xs font-bold transition-colors ${debtViewFilter === 'debt' ? 'border-rose-200 bg-rose-50 text-rose-700' : 'border-gray-200 bg-white text-gray-600 hover:bg-gray-50'}`}>Cần thu</button>
              <button type="button" onClick={() => setDebtViewFilter('credit')} className={`rounded-xl border px-3 py-3 text-xs font-bold transition-colors ${debtViewFilter === 'credit' ? 'border-blue-200 bg-blue-50 text-blue-700' : 'border-gray-200 bg-white text-gray-600 hover:bg-gray-50'}`}>Nợ khách</button>
            </div>
            <div className="grid grid-cols-3 gap-2">
              <select
                value={debtDateFilterMode}
                onChange={event => setDebtDateFilterMode(event.target.value)}
                className="min-w-0 rounded-xl border border-cyan-100 bg-cyan-50 px-2 py-3 text-[11px] font-black text-cyan-700 outline-none"
                aria-label="Lọc thời gian sổ nợ"
              >
                <option value="all">Ngày / tháng</option>
                <option value="day">Theo ngày</option>
                <option value="month">Theo tháng</option>
                <option value="year">Theo năm</option>
                <option value="custom">Ngày tự do</option>
              </select>
              <select
                value={debtTransactionSort}
                onChange={event => setDebtTransactionSort(event.target.value)}
                className="min-w-0 rounded-xl border border-gray-200 bg-white px-2 py-3 text-[11px] font-black text-gray-700 outline-none"
              >
                <option value="latest">Giao dịch mới</option>
                <option value="oldest">Giao dịch cũ</option>
                <option value="debt_desc">Nợ giảm dần</option>
                <option value="debt_asc">Nợ tăng dần</option>
              </select>
              <select
                value={debtSalesEmpId}
                onChange={event => setDebtSalesEmpId(event.target.value)}
                className="min-w-0 rounded-xl border border-gray-200 bg-white px-2 py-3 text-[11px] font-black text-gray-700 outline-none"
              >
                <option value="all">Tất cả NVKD</option>
                {debtManagerOptions.map(emp => (
                  <option key={emp.id} value={emp.id}>{emp.name || emp.phone || 'Nhân viên'}</option>
                ))}
              </select>
            </div>
            {debtDateFilterMode !== 'all' && (
              <div className="rounded-2xl border border-cyan-100 bg-cyan-50/50 p-3">
                {debtDateFilterMode === 'day' && (
                  <input
                    type="date"
                    value={debtFilterDate}
                    onChange={event => setDebtFilterDate(event.target.value || getTodayString())}
                    className="w-full rounded-xl border border-cyan-100 bg-white px-3 py-2.5 text-sm font-bold text-slate-700 outline-none"
                  />
                )}
                {debtDateFilterMode === 'month' && (
                  <input
                    type="month"
                    value={debtFilterMonth}
                    onChange={event => setDebtFilterMonth(event.target.value || getTodayString().slice(0, 7))}
                    className="w-full rounded-xl border border-cyan-100 bg-white px-3 py-2.5 text-sm font-bold text-slate-700 outline-none"
                  />
                )}
                {debtDateFilterMode === 'year' && (
                  <select
                    value={debtFilterYear}
                    onChange={event => setDebtFilterYear(event.target.value)}
                    className="w-full rounded-xl border border-cyan-100 bg-white px-3 py-2.5 text-sm font-bold text-slate-700 outline-none"
                  >
                    {debtFilterYears.map(year => <option key={year} value={year}>{year}</option>)}
                  </select>
                )}
                {debtDateFilterMode === 'custom' && (
                  <div className="grid grid-cols-2 gap-2">
                    <input
                      type="date"
                      value={debtCustomStartDate}
                      onChange={event => setDebtCustomStartDate(event.target.value)}
                      className="min-w-0 rounded-xl border border-cyan-100 bg-white px-2 py-2.5 text-xs font-bold text-slate-700 outline-none"
                      aria-label="Từ ngày"
                    />
                    <input
                      type="date"
                      value={debtCustomEndDate}
                      onChange={event => setDebtCustomEndDate(event.target.value)}
                      className="min-w-0 rounded-xl border border-cyan-100 bg-white px-2 py-2.5 text-xs font-bold text-slate-700 outline-none"
                      aria-label="Đến ngày"
                    />
                  </div>
                )}
              </div>
            )}
            <div className="flex items-center justify-between gap-3">
              <p className="text-[11px] text-gray-500">Đang hiển thị {filteredCustomers.length} khách phù hợp với bộ lọc hiện tại.</p>
              <button
                type="button"
                onClick={resetDebtFilters}
                className="shrink-0 rounded-full bg-slate-100 px-3 py-2 text-[11px] font-black text-slate-600"
              >
                Đặt lại
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="min-h-5 text-xs text-slate-500" role={preparedDebtSearch.error?'alert':'status'}>
        {preparedDebtSearch.error?'Không thể tìm kiếm. Hãy mở lại Sổ nợ để thử lại.':preparedDebtSearch.pending?'Đang tìm kiếm…':''}
      </div>
      <fieldset disabled={preparedDebtSearch.pending||Boolean(preparedDebtSearch.error)}
        aria-busy={preparedDebtSearch.pending}
        data-hd-debt-search-query={!preparedDebtSearch.pending&&!preparedDebtSearch.error?debtSearchQuery:undefined}
        data-hd-search-retained={Boolean(retainedDebtPage)}
        onClickCapture={event=>{if(preparedDebtSearch.pending||preparedDebtSearch.error){event.preventDefault();event.stopPropagation();}}}
        className="m-0 min-w-0 space-y-3 border-0 p-0">
        {displayedDebtPage.items.map(customer => (
          <div key={customer.id} onClick={() => openDebtCustomerDetail(customer)} className="hd-render-contained bg-white p-4 rounded-xl shadow-sm border border-gray-50 flex justify-between items-center cursor-pointer hover:bg-gray-50 transition">
            <div>
              <h3 className="font-bold text-gray-800 text-sm">{customer.name}</h3>
              <span className="text-[10px] text-gray-500 flex items-center mt-1"><MapPin size={10} className="mr-1"/> {customer.address || 'Chưa có địa chỉ'}</span>
              {customer.debtLimitStatus?.exceeded && (
                <span className="mt-2 inline-flex rounded-full border border-rose-100 bg-rose-50 px-2 py-1 text-[10px] font-black text-rose-700">
                  Vượt hạn mức {formatCurrency(customer.debtLimitStatus.overAmount)} đ
                </span>
              )}
            </div>
            <div className="text-right">
              {customer.ledger.currentDebt > 0 ? (
                <>
                  <span className="block font-bold text-red-500">{formatCurrency(customer.ledger.currentDebt)} đ</span>
                  <span className="text-[10px] text-gray-400">Cần thu</span>
                </>
              ) : (
                <>
                  <span className="block font-bold text-blue-500">{formatCurrency(customer.ledger.creditBalance)} đ</span>
                  <span className="text-[10px] text-gray-400">Nợ khách</span>
                </>
              )}
            </div>
          </div>
        ))}

        {!preparedDebtSearch.pending&&!preparedDebtSearch.error&&filteredCustomers.length === 0 && (
          <div className="bg-white rounded-xl border border-gray-100 p-6 text-center text-sm text-gray-400">
            {isDriver
              ? 'Bạn chưa được chủ doanh nghiệp cấp quyền xem công nợ cho khách hàng nào, hoặc các khách đã được cấp hiện không còn công nợ.'
              : 'Không có khách hàng nào đang nợ hoặc nợ khách theo bộ lọc hiện tại.'}
          </div>
        )}
        <ListPagination pagination={displayedDebtPage} label="Phân trang công nợ" />
      </fieldset>
    </div>
  );
}

